/* =========================================================================
   SELEZIONE SQUADRA
   ========================================================================= */
function isBotMode() {
    return gameState.mode === 'bot';
}

function showModeSelection() {
    const root = document.getElementById("modal-root");
    root.innerHTML = `<div class="modal-overlay"><div class="modal-box pass-device-box">
        <h3>Scegli la modalità di gioco</h3>
        <p>Seleziona come vuoi giocare questa partita.</p>
        <div id="mode-selection-btns"></div>
    </div></div>`;

    const holder = document.getElementById("mode-selection-btns");
    const localBtn = document.createElement("button");
    localBtn.innerText = "1v1 locale";
    localBtn.style.background = "#2980b9";
    localBtn.onclick = () => chooseGameMode('local');

    const botBtn = document.createElement("button");
    botBtn.innerText = "Giocatore contro Bot";
    botBtn.style.background = "#27ae60";
    botBtn.onclick = () => chooseGameMode('bot');

    holder.appendChild(localBtn);
    holder.appendChild(botBtn);
}

function chooseGameMode(mode) {
    gameState.mode = mode;
    gameState.phase = 'selection';
    gameState.currentPlayerSelecting = 1;
    gameState.p1TeamTemplates = [];
    gameState.p2TeamTemplates = [];
    selectedIndices = [];

    closeModal();
    document.getElementById("select-screen").classList.remove("hidden");
    document.getElementById("battle-screen").classList.add("hidden");
    document.getElementById("p2-name-label").innerText = mode === 'bot' ? "Bot" : "Giocatore 2";
    document.getElementById("selector-title").innerText = "Turno: Giocatore 1 (Selezionati: 0/4)";
    document.getElementById("confirm-selection").innerText = "Conferma Squadra Giocatore 1";
    document.getElementById("confirm-selection").disabled = true;
    initRosterSelection();
}

function initRosterSelection() {
    const grid = document.getElementById("roster-grid");
    grid.innerHTML = "";
    RAW_POKEMON_DATA.forEach((poke, idx) => {
        let card = document.createElement("div");
        card.className = "poke-card";
        card.id = `poke-card-${idx}`;
        card.onclick = () => toggleSelectPokemon(idx);
        card.innerHTML = `
            <h4>${pokeThumbHtml(poke, 'poke-thumb')}${poke.name} (${poke.gender})</h4>
            <p><b>Tipi:</b> ${poke.types.join(", ")}</p>
            <p><b>Abilità:</b> ${poke.ability}</p>
            <p><b>Base:</b> HP:${poke.base.HP} Atk:${poke.base.Atk} Def:${poke.base.Def} SpA:${poke.base.SpA} SpD:${poke.base.SpD} Spe:${poke.base.Spe}</p>
        `;
        grid.appendChild(card);
    });
}

let selectedIndices = [];
function toggleSelectPokemon(idx) {
    let card = document.getElementById(`poke-card-${idx}`);
    if (selectedIndices.includes(idx)) {
        selectedIndices = selectedIndices.filter(i => i !== idx);
        card.classList.remove("selected");
    } else if (selectedIndices.length < 4) {
        selectedIndices.push(idx);
        card.classList.add("selected");
    }
    document.getElementById("confirm-selection").disabled = selectedIndices.length !== 4;
}

function confirmPlayerSelection() {
    if (gameState.currentPlayerSelecting === 1) {
        gameState.p1TeamTemplates = [...selectedIndices];
        selectedIndices = [];
        document.querySelectorAll(".poke-card").forEach(c => c.classList.remove("selected"));

        if (isBotMode()) {
            gameState.p2TeamTemplates = chooseBotTeam(gameState.p1TeamTemplates);
            startBattle();
            return;
        }

        gameState.currentPlayerSelecting = 2;
        document.getElementById("selector-title").innerText = "Turno: Giocatore 2 (Selezionati: 0/4)";
        document.getElementById("confirm-selection").innerText = "Avvia Battaglia";
        document.getElementById("confirm-selection").disabled = true;
        // Popup di passaggio dispositivo tra la selezione di P1 e quella di P2
        showPassDevice(2, () => {
            initRosterSelection();
        });
    } else {
        gameState.p2TeamTemplates = [...selectedIndices];
        startBattle();
    }
}

/* =========================================================================
   CLASSE POKEMON DA BATTAGLIA
   ========================================================================= */
class BattlePokemon {
    constructor(template, trainerId) {
        this.name = template.name;
        this.image = template.image || null;
        this.originalGender = template.gender;
        this.gender = template.gender;
        this.originalTypes = [...template.types];
        this.types = [...template.types];
        this.ability = template.ability;
        this.moves = JSON.parse(JSON.stringify(template.moves));
        this.trainerId = trainerId;

        this.maxHp = Math.floor((2 * template.base.HP + 31) * 50 / 100) + 60;
        this.hp = this.maxHp;
        this.baseStats = {
            Atk: Math.floor((2 * template.base.Atk + 31) * 50 / 100) + 5,
            Def: Math.floor((2 * template.base.Def + 31) * 50 / 100) + 5,
            SpA: Math.floor((2 * template.base.SpA + 31) * 50 / 100) + 5,
            SpD: Math.floor((2 * template.base.SpD + 31) * 50 / 100) + 5,
            Spe: Math.floor((2 * template.base.Spe + 31) * 50 / 100) + 5
        };
        this.stages = { Atk:0, Def:0, SpA:0, SpD:0, Spe:0 };
        this.status = { type:null, counter:0, sleepTurns:0 };
        this.isFainted = false;
        this.activeSlot = null; // 0/1 while in campo

        this.v = { // volatile flags, resettate quando esce dal campo
            confused:false,
            fungo:false,
            da:false,
            trapped:false,
            forcedMove:null,     // {name, turnsLeft}
            moveLockout:{},      // {moveName: turnsLeft}
            mustAttackTarget:null, // riferimento pokemon da colpire per forza (Scopiamo)
            redirectTurns:0,     // Svenimento: gli avversari devono colpire lui
            protectStreak:0,
            damageReduction:0,   // % riduzione danno temporanea propria
            hasActedOnce:false,
            lastMoveUsed:null,
            frozenAtkNoLeave:null, // Pescare/Croste: chi lo blocca in campo
            accuracyPenalty:0,   // Birra: penalità di precisione relativa (%)
            giaLastDamagingRound:-Infinity // Ottimizzazione: ultimo round in cui ha usato una mossa offensiva
        };
    }

    resetOnSwitchOut() {
        this.stages = { Atk:0, Def:0, SpA:0, SpD:0, Spe:0 };
        this.v.confused = false;
        this.v.trapped = false;
        this.v.forcedMove = null;
        this.v.moveLockout = {};
        this.v.mustAttackTarget = null;
        this.v.redirectTurns = 0;
        this.v.protectStreak = 0;
        this.v.frozenAtkNoLeave = null;
        this.v.accuracyPenalty = 0;
        this.v.giaLastDamagingRound = -Infinity;
        // Sleep e Frozen mantengono il proprio avanzamento anche quando il Pokémon
        // esce dal campo. Gli altri status conservano invece il comportamento
        // precedente: il loro contatore viene azzerato allo switch.
        if (this.status.type !== 'Sleep' && this.status.type !== 'Frozen') {
            this.status.counter = 0;
        }
        this.types = [...this.originalTypes];
        this.gender = this.originalGender;
        this.activeSlot = null;
    }
}

/* =========================================================================
   HELPERS DI CAMPO
   ========================================================================= */
function allActive() { return [...gameState.p1Active, ...gameState.p2Active].filter(p => p && !p.isFainted); }
function allPokemonTargets(attacker) { return allActive().filter(p => p !== attacker); }
function sideActive(trainerId) { return (trainerId===1?gameState.p1Active:gameState.p2Active).filter(p=>p && !p.isFainted); }
function enemyActive(trainerId) { return sideActive(trainerId===1?2:1); }
function allyOf(poke) { return sideActive(poke.trainerId).find(p=>p!==poke); }
function fieldHasAbility(abilityName) { return allActive().some(p=>p.ability===abilityName); }

function setTerreno(type, poke) {
    gameState.field.terreno = type;
    gameState.field.terrenoTurns = 5;
    printLog(`🌿 ${pname(poke)} imposta il Terreno ${type}!`);
}
function setClima(type, poke) {
    gameState.field.clima = type;
    gameState.field.climaTurns = 5;
    printLog(`☁️ ${pname(poke)} imposta il Clima ${type}!`);
}

/* =========================================================================
   STATISTICHE EFFETTIVE (con stage + abilità passive)
   ========================================================================= */
function abilityStageDelta(poke, stat) {
    let d = 0;
    const ally = allyOf(poke);
    if (poke.ability === "Grounding" && gameState.field.terreno) { if (stat==='Spe') d += 1; }
    if (poke.ability === "camerata" && ally) {
        if (ally.gender === 'Maschio') { if (stat==='Atk'||stat==='Spe') d += 1; }
        if (ally.types.includes('Terrone') || ally.types.includes('Esotico')) { if (stat==='Atk') d -= 1; }
    }
    if (poke.ability === "Baffo" && ally && ally.gender === 'Maschio') { if (stat==='Def'||stat==='Atk') d += 1; }
    if (poke.ability === "Tolleranza" ||  fieldHasAbility('Tolleranza')) {
        if ((poke.types.includes('Esotico') || poke.types.includes('Terrone')) && (stat==='Def'||stat==='SpD')) d += 2;
    }
    if (poke.ability === "Passato Oscuro" && (gameState.field.clima==='Fumo' || gameState.field.terreno==='Alcol')) {
        if (stat==='Spe') d += 1;
    }
    return d;
}

function flatStatMultiplier(poke, stat) {
    let mult = 1;
    if (poke.ability === "Grounding" && gameState.field.clima === "Fumo") {
        if (stat==='Def' || stat==='Spe') mult *= 0.9;
    }
    return mult;
}

function clampStage(v){ return Math.max(-6, Math.min(6, v)); }

// Calcola il valore "grezzo" di una statistica (senza bonus incrociati da Ottimizzazione),
// applicando stage (o uno stage esplicito passato come override) + moltiplicatori flat.
function effStatBase(poke, statKey, stageOverride) {
    const rawStage = (stageOverride !== undefined) ? stageOverride : (poke.stages[statKey] + abilityStageDelta(poke, statKey));
    const stage = clampStage(rawStage);
    let val = Math.floor(poke.baseStats[statKey] * STAGE_MODS[stage]);
    val = Math.floor(val * flatStatMultiplier(poke, statKey));
    return val;
}

function getStat(poke, stat) {
    if (stat === 'HP') return poke.hp;
    // Ottimizzazione (Giana), lato offensivo: SpA = SpA + 0.5*Atk + 0.25*Def + 0.25*SpD
    if (poke.ability === 'Ottimizzazione' && stat === 'SpA') {
        const spa = effStatBase(poke, 'SpA');
        const atk = effStatBase(poke, 'Atk');
        const def = effStatBase(poke, 'Def');
        const spd = effStatBase(poke, 'SpD');
        return Math.max(1, spa + Math.floor(0.5*atk) + Math.floor(0.25*def) + Math.floor(0.25*spd));
    }
    return Math.max(1, effStatBase(poke, stat));
}

// Statistica difensiva usata nel calcolo del danno: gestisce anche il bonus incrociato di
// Ottimizzazione quando Giana SUBISCE una mossa fisica (Def) o speciale (SpD).
// stageOverride: stage già calcolato dal chiamante (es. clampato a <=0 per crit/Brutto Colpo).
function getDefensiveStat(defender, statKey, stageOverride) {
    if (defender.ability === 'Ottimizzazione') {
        const atk = effStatBase(defender, 'Atk');
        const def = effStatBase(defender, 'Def');
        const spa = effStatBase(defender, 'SpA');
        const spd = effStatBase(defender, 'SpD');
        if (statKey === 'SpD') {
            const spdMain = effStatBase(defender, 'SpD', stageOverride);
            return Math.max(1, spdMain + Math.floor(0.5*def) + Math.floor(0.25*atk) + Math.floor(0.25*spa));
        } else { // Def
            const defMain = effStatBase(defender, 'Def', stageOverride);
            return Math.max(1, defMain + Math.floor(0.5*spd) + Math.floor(0.25*atk) + Math.floor(0.25*spa));
        }
    }
    return Math.max(1, effStatBase(defender, statKey, stageOverride));
}

/* =========================================================================
   MODIFICHE DI STAGE (rispetta Innocenza / Doppiatore)
   ========================================================================= */
function changeStage(target, deltas, opts={}) {
    if (fieldHasAbility('Innocenza') && !opts.forceThroughInnocenza) {
        printLog(`🚫 Innocenza impedisce cambi di statistiche in campo!`);
        return;
    }
    let doubled = false;
    if (allActive().some(p => p.ability==='Doppiatore' && p.trainerId===target.trainerId) && Math.random() < 0.6) {
        doubled = true;
    }
    Object.keys(deltas).forEach(stat => {
        let d = deltas[stat] * (doubled ? 2 : 1);
        target.stages[stat] = clampStage(target.stages[stat] + d);
    });
    printLog(`📊 ${pname(target)}: ${Object.entries(deltas).map(([k,v])=>`${k} ${v>0?'+':''}${v}${doubled?' (raddoppiato!)':''}`).join(', ')}`);
}

/* =========================================================================
   STATO (Status conditions)
   ========================================================================= */
function tryInflictStatus(target, statusType, source) {
    if (target.isFainted) return false;
    if (target.ability === 'Fascino di Pie' && (statusType==='Iperavvelenato')) return false;
    if (EXCLUSIVE_STATUSES.includes(statusType)) {
        if (target.status.type) { printLog(`${pname(target)} è già affetto da ${target.status.type}, ${statusType} non ha effetto.`); return false; }
        target.status = { type: statusType, counter:0, sleepTurns:0 };
        printLog(`☠️ ${pname(target)} ora ha lo stato ${statusType}!`);
        return true;
    }
    if (statusType === 'Fungo') { target.v.fungo = true; printLog(`🍄 ${pname(target)} ha lo stato Fungo!`); return true; }
    if (statusType === 'Confuso') {
        target.v.confused = true;
        printLog(`💫 ${pname(target)} è confuso!`);
        return true;
    }
    if (statusType === 'DA') { target.v.da = true; printLog(`🍽️ ${pname(target)} ha lo stato DA!`); return true; }
    return false;
}

function healPoke(target, amountPct) {
    if (target.v.da) { printLog(`${pname(target)} non può curarsi: stato DA attivo!`); return; }
    const heal = Math.floor(target.maxHp * amountPct);
    target.hp = Math.min(target.maxHp, target.hp + heal);
    printLog(`💚 ${pname(target)} recupera ${heal} HP!`);
}

/* =========================================================================
   TIPI / DANNO
   ========================================================================= */
function typeMultiplier(moveType, defenderTypes) {
    let mult = 1;
    defenderTypes.forEach(dt => {
        const entry = TYPE_CHART[dt];
        if (!entry) return;
        if (entry.immune && entry.immune.includes(moveType)) mult *= 0;
        else if (entry.weak && entry.weak.includes(moveType)) mult *= 2;
        else if (entry.resist && entry.resist.includes(moveType)) mult *= 0.5;
    });
    return mult;
}

function checkAccuracy(attacker, defender, move) {
    if (move.effect === 'bang') return true; // Bang! non evitabile
    let acc = (move.accuracy != null) ? move.accuracy : 100;
    // Tutti i modificatori di precisione sono relativi (moltiplicativi), non sottrattivi.
    if (fieldHasAbility('Fascino di Pie') && attacker.gender === 'Femmina') acc *= 0.8;
    if (gameState.field.terreno === 'Alcol' && move.type !== 'Alcol' && !attacker.types.includes('Alcol')) acc *= 0.9;
    if (attacker.v.accuracyPenalty) acc *= Math.max(0, 1 - attacker.v.accuracyPenalty/100);
    acc = Math.max(0, Math.min(100, acc));
    return Math.random() * 100 < acc;
}

function computeDamage(attacker, defender, move, {isCrit=false, numTargets=1, forceStab=false, bruttoColpo=false}={}) {
    if (move.bp === 0) return 0;
    const isSpec = move.category === 'Speciale';
    let aStat = getStat(attacker, isSpec ? 'SpA' : 'Atk');
    let dStatKey = isSpec ? 'SpD' : 'Def';
    let dStage = defender.stages[dStatKey] + abilityStageDelta(defender, dStatKey);
    if (isCrit || bruttoColpo) dStage = Math.min(dStage, 0); // ignora boost difensivi positivi
    let dStat = getDefensiveStat(defender, dStatKey, dStage);

    let base = Math.floor((22 * move.bp * aStat / dStat) / 50) + 2;
    let stab = (attacker.types.includes(move.type) || forceStab || move.stab || attacker.ability === 'goblin') ? 1.5 : 1.0;
    if (move.effect === 'fluidodinamica' && defender.types.includes('Alcol')) base *= 2;
    if (move.sound && attacker.ability === 'Gran Voce') base = Math.floor(base * 1.5);

    let tMod = typeMultiplier(move.type, defender.types);
    if (tMod === 0) return { dmg:0, tMod };

    let multiTargetMod = numTargets > 1 ? 0.75 : 1;
    let critMod = (isCrit || bruttoColpo) ? 1.5 : 1;

    let dmg = Math.floor(base * stab * tMod * multiTargetMod * critMod);

    // Riduzioni danno da abilità/effetti
    if (fieldHasAbility('Fascino di Pie') && defender.gender === 'Femmina') dmg = Math.floor(dmg * 0.8);
    if (defender.ability === 'Gluten Free' && (move.type === 'Alcol' || move.type === 'Cibo')) dmg = Math.floor(dmg * 0.75);
    if (defender.ability === 'Divano e Canna' && move.type === 'Terrone') dmg = Math.floor(dmg * 0.75);
    if (defender.ability === 'Passato Oscuro' && (gameState.field.clima === 'Fumo' || gameState.field.terreno === 'Alcol')) dmg = Math.floor(dmg * 0.85);
    if (gameState.field.clima === 'Fumo' && defender.types.includes('Fumo')) dmg = Math.floor(dmg * 0.9);
    const lallaAlly = sideActive(defender.trainerId).find(p => p.name === 'Lalla');
    if (lallaAlly && lallaAlly !== defender) dmg = Math.floor(dmg * 0.85);
    const side = defender.trainerId === 1 ? gameState.p1Side : gameState.p2Side;
    if (side.dmgReductionTurns > 0) dmg = Math.floor(dmg * (1 - side.dmgReductionPct));

    return { dmg: Math.max(1, dmg), tMod };
}

/* =========================================================================
   BATTAGLIA: AVVIO
   ========================================================================= */
function startBattle() {
    document.getElementById("select-screen").classList.add("hidden");
    document.getElementById("battle-screen").classList.remove("hidden");

    gameState.p1Team = gameState.p1TeamTemplates.map(idx => new BattlePokemon(RAW_POKEMON_DATA[idx], 1));
    gameState.p2Team = gameState.p2TeamTemplates.map(idx => new BattlePokemon(RAW_POKEMON_DATA[idx], 2));

    gameState.p1Active = [gameState.p1Team[0], gameState.p1Team[1]];
    gameState.p2Active = [gameState.p2Team[0], gameState.p2Team[1]];
    gameState.p1Active.forEach((p,i)=>p.activeSlot=i);
    gameState.p2Active.forEach((p,i)=>p.activeSlot=i);

    document.getElementById("p2-name-label").innerText = isBotMode() ? "Bot" : "Giocatore 2";
    printLog(`⚔️ La battaglia VGC ha inizio tra Giocatore 1 e ${isBotMode() ? "il Bot" : "Giocatore 2"}!`);
    allActive().forEach(p => triggerEntryAbility(p));
    updateUI();
    // Il popup serve solo nella partita locale: il Bot prende il controllo automaticamente.
    if (isBotMode()) promptNextMove();
    else showPassDevice(1, () => promptNextMove());
}

function triggerEntryAbility(poke) {
    switch (poke.ability) {
        case "Consegna delle Verifiche": setClima("Fumo", poke); break;
        case "Giro di Shot":
            setTerreno("Alcol", poke);
            allActive().forEach(p => tryInflictStatus(p, 'Confuso'));
            break;
        case "Soppressata": setTerreno("Calabro", poke); break;
        case "Divano e Canna": setTerreno("Chill", poke); setClima("Fumo", poke); break;
        case "Poliglotta":
            printLog(`🗣️ ${pname(poke)} rivela le mosse avversarie:`);
            enemyActive(poke.trainerId).forEach(e => printLog(`&nbsp;&nbsp;${pname(e)}: ${e.moves.map(m=>m.name).join(', ')}`));
            break;
        case "Infermiera":
            sideActive(poke.trainerId).forEach(a => { a.status = {type:null,counter:0,sleepTurns:0}; a.v.fungo=false; a.v.da=false; });
            printLog(`💊 ${pname(poke)} cura tutti gli status della squadra!`);
            break;
        case "discussione": {
            const opp = enemyActive(poke.trainerId)[poke.activeSlot] || enemyActive(poke.trainerId)[0];
            if (opp) { tryInflictStatus(opp, 'Confuso'); changeStage(opp, {Def:-1, SpD:-1}); }
            break;
        }
        case "Richiamo di Becchio": {
            const becchioPresent = fieldHasAbility('Poppe A Casa!');
            changeStage(poke, {Def:1, SpD: becchioPresent ? 2 : 1}, {forceThroughInnocenza:true});
            break;
        }
        case "Poppe A Casa!": {
            const poppe = allActive().find(p => p.name === 'Poppe');
            if (poppe) changeStage(poppe, {Atk:-1, SpA:-1, Def:1, SpD:1}, {forceThroughInnocenza:true});
            else enemyActive(poke.trainerId).forEach(e => changeStage(e, {Def:-1}, {forceThroughInnocenza:true}));
            break;
        }
    }
}

function printLog(text) {
    let logEl = document.getElementById("log");
    logEl.innerHTML += `<div>${text}</div>`;
    logEl.scrollTop = logEl.scrollHeight;
}

// Etichetta un Pokémon con il suo giocatore (es. "Pie (G1)"). Usata in TUTTI i messaggi di log
// che citano un Pokémon per nome, perché due squadre possono scegliere lo stesso Pokémon e il
// nome da solo (es. "Pie") sarebbe ambiguo su quale dei due stia effettivamente agendo/subendo.
function pname(poke) {
    if (!poke) return '???';
    return `${poke.name} (G${poke.trainerId})`;
}

// Genera il tag <img> per un Pokémon SOLO se ha un'immagine associata (poke.image valorizzato).
// Se il campo è null/assente, restituisce stringa vuota e la UI resta quella testuale attuale.
// onerror nasconde l'immagine anche se il percorso è impostato ma il file non si carica
// correttamente, così un riferimento rotto non rompe mai il layout.
function pokeThumbHtml(poke, sizeClass) {
    if (!poke || !poke.image) return '';
    return `<img src="${poke.image}" class="${sizeClass}" loading="lazy" onerror="this.remove()" alt="${poke.name}">`;
}

/* =========================================================================
   RENDER
   ========================================================================= */
function statusLabel(poke) {
    let tags = [];
    if (poke.status.type) tags.push(poke.status.type);
    if (poke.v.confused) tags.push('Confuso');
    if (poke.v.fungo) tags.push('Fungo');
    if (poke.v.da) tags.push('DA');
    return tags.map(t=>`<span class="status-tag">${t}</span>`).join('');
}
function stageLabel(poke) {
    return Object.entries(poke.stages).filter(([k,v])=>v!==0)
        .map(([k,v])=>`<span class="stage-tag">${k} ${v>0?'+':''}${v}</span>`).join('');
}

function updateUI() {
    const f = gameState.field;
    document.getElementById("field-status-bar").innerHTML = `
        <span>Terreno: ${f.terreno || 'Nessuno'} ${f.terreno?`(${f.terrenoTurns})`:''}</span>
        <span>Clima: ${f.clima || 'Nessuno'} ${f.clima?`(${f.climaTurns})`:''}</span>
    `;
    renderSide(1); renderSide(2);
}

function renderSide(trainerId) {
    const active = trainerId===1 ? gameState.p1Active : gameState.p2Active;
    for (let i=0;i<2;i++) {
        let p = active[i];
        let slotEl = document.getElementById(`p${trainerId}-slot-${i}`);
        if (p && !p.isFainted) {
            slotEl.innerHTML = `<b>${pokeThumbHtml(p, 'poke-thumb-battle')}${p.name}</b> (${p.gender==='Maschio'?'M':'F'}) — ${p.types.join("/")} — ${p.ability}
                ${statusLabel(p)}<br>HP: ${p.hp}/${p.maxHp}
                <div class="hp-bar-container"><div class="hp-bar-fill" style="width:${Math.max(0,(p.hp/p.maxHp)*100)}%"></div></div>
                ${stageLabel(p)}`;
        } else {
            slotEl.innerHTML = `<b>Slot ${i+1}:</b> KO / Vuoto`;
        }
    }
}

/* =========================================================================
   MODALI (target / switch / scelta mossa da bloccare)
   ========================================================================= */
function showModal(title, options) {
    const root = document.getElementById("modal-root");
    root.innerHTML = `<div class="modal-overlay"><div class="modal-box"><h3>${title}</h3><div id="modal-opts"></div></div></div>`;
    const opts = document.getElementById("modal-opts");
    options.forEach(o => {
        let b = document.createElement("button");
        b.innerText = o.label;
        b.onclick = () => { closeModal(); o.onClick(); };
        opts.appendChild(b);
    });
}
function closeModal() { document.getElementById("modal-root").innerHTML = ""; }

// Popup "Passa il dispositivo al Giocatore X": blocca l'interfaccia finché il giocatore
// che deve ricevere il dispositivo non conferma di essere pronto. Usato sia tra la
// selezione delle squadre sia a inizio di ogni nuovo turno di battaglia.
function showPassDevice(playerNum, callback) {
    const root = document.getElementById("modal-root");
    root.innerHTML = `<div class="modal-overlay"><div class="modal-box pass-device-box">
        <h3>📱 Passa il dispositivo al Giocatore ${playerNum}</h3>
        <p>Assicurati che l'altro giocatore non stia guardando lo schermo, poi continua.</p>
        <div id="pass-device-btn-holder"></div>
    </div></div>`;
    const holder = document.getElementById("pass-device-btn-holder");
    const btn = document.createElement("button");
    btn.innerText = `Continua come Giocatore ${playerNum}`;
    btn.style.background = "#27ae60";
    btn.onclick = () => { root.innerHTML = ""; callback(); };
    holder.appendChild(btn);
}

// Ripristina la struttura standard dell'area di controllo (etichetta + griglia mosse +
// pulsanti Cambia/Salta), usata dopo che era stata sostituita dal bottone "Prosegui al
// prossimo turno" (o da qualunque altro contenuto temporaneo).
function restoreControlsArea() {
    document.getElementById("controls-area").innerHTML = `
        <div>
            <h4 id="current-actor-label">Tocca a: -</h4>
            <div class="moves-grid" id="moves-grid"></div>
        </div>
        <div style="display: flex; flex-direction: column; gap: 5px; justify-content: center;">
            <button class="secondary-btn" onclick="openSwitchMenu()">Cambia Pokémon</button>
            <button class="secondary-btn quit-battle-btn" onclick="quitBattle()">Abbandona battaglia</button>
        </div>`;
}

// Sostituisce l'area di controllo con un unico bottone "Prosegui al prossimo turno",
// mostrato dopo la risoluzione di tutte le mosse e degli effetti di fine turno (status,
// campo, ecc.), lasciando il log ben visibile finché il giocatore non decide di continuare.
function showContinueButton() {
    const area = document.getElementById("controls-area");
    area.innerHTML = `
        <div style="grid-column: 1 / -1; text-align:center;">
            <button id="continue-turn-btn">▶️ Prosegui al prossimo turno</button>
        </div>`;
    document.getElementById("continue-turn-btn").onclick = () => {
        area.innerHTML = "";
        handleForcedSwitches(finishRound);
    };
}

// Mostra, al posto della griglia mosse, il bottone "Termina Partita" quando la battaglia
// è conclusa (usato da checkWinner()). Al click si apre il popup che offre la possibilità
// di iniziare una nuova partita indipendente nella stessa sessione.
function showEndGameButton() {
    const area = document.getElementById("controls-area");
    area.innerHTML = `
        <div style="grid-column: 1 / -1; text-align:center;">
            <h3 style="margin:0 0 10px 0;">Partita Terminata</h3>
            <button id="end-game-btn" style="background:#e74c3c;">🏁 Termina Partita</button>
        </div>`;
    document.getElementById("end-game-btn").onclick = () => {
        area.innerHTML = "";
        showPlayAgainPopup();
    };
}

// Popup mostrato dopo aver premuto "Termina Partita": offre la possibilità di giocare
// un'altra partita, riportando il gioco allo stato iniziale (selezione squadre).
function showPlayAgainPopup() {
    const root = document.getElementById("modal-root");
    root.innerHTML = `<div class="modal-overlay"><div class="modal-box pass-device-box">
        <h3>🎮 Partita conclusa!</h3>
        <p>Vuoi giocare un'altra partita? Si tornerà alla scelta della modalità e delle squadre.</p>
        <div id="play-again-btn-holder"></div>
    </div></div>`;
    const holder = document.getElementById("play-again-btn-holder");
    const btn = document.createElement("button");
    btn.innerText = "Gioca di nuovo";
    btn.style.background = "#27ae60";
    btn.onclick = () => { root.innerHTML = ""; resetGame(); };
    holder.appendChild(btn);
}

// Riporta il gioco esattamente allo stato iniziale (come al primo caricamento della
// pagina): azzera gameState, le variabili di turno e la selezione squadre, svuota il
// log e torna alla schermata di selezione Pokémon per Giocatore 1. Permette così di
// giocare più partite indipendenti nella stessa sessione senza ricaricare la pagina.
function resetGame() {
    gameState = {
        phase:'selection',
        mode:null,
        currentPlayerSelecting:1,
        p1TeamTemplates:[], p2TeamTemplates:[],
        p1Team:[], p2Team:[],
        p1Active:[null,null], p2Active:[null,null],
        field:{ terreno:null, terrenoTurns:0, clima:null, climaTurns:0 },
        p1Side:{ dmgReductionPct:0, dmgReductionTurns:0 },
        p2Side:{ dmgReductionPct:0, dmgReductionTurns:0 },
        roundNumber:0,
        pendingReturn:[]
    };
    currentTrainerTurn = 1;
    currentSlotTurn = 0;
    roundActions = [];
    selectedIndices = [];

    document.getElementById("log").innerHTML = "";
    document.getElementById("battle-screen").classList.add("hidden");
    document.getElementById("select-screen").classList.remove("hidden");
    document.getElementById("selector-title").innerText = "Turno: Giocatore 1 (Selezionati: 0/4)";
    document.getElementById("confirm-selection").innerText = "Conferma Squadra Giocatore 1";
    document.getElementById("confirm-selection").disabled = true;
    restoreControlsArea();
    initRosterSelection();
    showModeSelection();
}

/* =========================================================================
   TURNO: SELEZIONE AZIONI
   ========================================================================= */
let currentTrainerTurn = 1;
let currentSlotTurn = 0;
let roundActions = [];

function livingTeam(trainerId){ return (trainerId===1?gameState.p1Team:gameState.p2Team).filter(p=>!p.isFainted); }

function checkWinner() {
    let p1Alive = livingTeam(1).length>0;
    let p2Alive = livingTeam(2).length>0;
    if (!p1Alive || !p2Alive) {
        const winnerLabel = p1Alive ? "Giocatore 1" : (isBotMode() ? "il Bot" : "Giocatore 2");
        printLog(`🏆 <b>FINE PARTITA! Vince ${winnerLabel}!</b>`);
        showEndGameButton();
        return true;
    }
    return false;
}

function promptNextMove() {
    if (checkWinner()) return;

    // In modalità Bot il secondo giocatore viene gestito automaticamente, senza
    // mostrare la griglia di mosse né il popup di passaggio dispositivo.
    if (isBotMode() && currentTrainerTurn === 2) {
        botPromptNextMove();
        return;
    }

    restoreControlsArea();

    let activePoke = currentTrainerTurn===1 ? gameState.p1Active[currentSlotTurn] : gameState.p2Active[currentSlotTurn];
    if (!activePoke || activePoke.isFainted) { advanceActor(); return; }

    // Mossa forzata a ripetere?
    if (activePoke.v.forcedMove && activePoke.v.forcedMove.turnsLeft > 0) {
        const mv = activePoke.moves.find(m=>m.name===activePoke.v.forcedMove.name);
        if (mv) {
            printLog(`🔁 ${pname(activePoke)} è costretto a ripetere ${mv.name}!`);
            queueAction(activePoke, mv, defaultTargetFor(activePoke, mv));
            activePoke.v.forcedMove.turnsLeft--;
            advanceActor();
            return;
        }
    }

    document.getElementById("current-actor-label").innerText = `Giocatore ${currentTrainerTurn} - Tocca a: ${activePoke.name} (Slot ${currentSlotTurn+1})`;
    let grid = document.getElementById("moves-grid");
    grid.innerHTML = "";
    activePoke.moves.forEach((move, mIdx) => {
        let btn = document.createElement("button");
        const lockedByCounter = activePoke.v.moveLockout[move.name] > 0;
        // Ottimizzazione: Giana non può usare due mosse offensive (Fisico/Speciale) in due turni consecutivi
        const giaLocked = activePoke.ability === 'Ottimizzazione' && move.category !== 'Stato' && activePoke.v.giaLastDamagingRound === gameState.roundNumber;
        const locked = lockedByCounter || giaLocked;
        btn.innerText = `${move.name} (${move.type})${locked?' 🔒':''}`;
        btn.disabled = !!locked;
        btn.onclick = () => onMoveChosen(activePoke, move);
        grid.appendChild(btn);
    });
}

/* =========================================================================
   INTELLIGENZA DEL BOT
   ========================================================================= */
function botTeamValue(data) {
    const b = data.base;
    const total = b.HP + b.Atk + b.Def + b.SpA + b.SpD + b.Spe;
    const bestAttack = Math.max(b.Atk, b.SpA);
    const bestMoves = data.moves.reduce((sum, move) => sum + (move.bp || 0), 0);
    const hasUtility = data.moves.some(move => move.category === 'Stato');
    return total + bestAttack * 0.8 + bestMoves * 0.35 + (hasUtility ? 24 : 0) + b.HP * 0.2;
}

function botTeamRoles(data) {
    const b = data.base;
    return {
        physical: b.Atk >= b.SpA * 1.12,
        special: b.SpA >= b.Atk * 1.12,
        utility: data.moves.some(move => move.category === 'Stato'),
        fast: b.Spe >= 80,
        durable: b.HP + b.Def + b.SpD >= 245
    };
}

function botTeamCandidateScore(candidate, chosen, playerIndices) {
    const data = candidate.data;
    const roles = botTeamRoles(data);
    const chosenData = chosen.map(index => RAW_POKEMON_DATA[index]);
    const chosenTypes = chosenData.flatMap(pokemon => pokemon.types);
    const playerData = playerIndices.map(index => RAW_POKEMON_DATA[index]);

    let score = candidate.score;

    // Premia tipi e mosse che ampliano la squadra invece di duplicarla.
    const newTypes = data.types.filter(type => !chosenTypes.includes(type)).length;
    score += newTypes * 15;
    score -= data.types.filter(type => chosenTypes.includes(type)).length * 3;

    // Cerca copertura utile contro i tipi scelti dal giocatore.
    const coveredPlayerTypes = new Set();
    data.moves.forEach(move => {
        if (!move.bp) return;
        playerData.forEach(player => {
            if (typeMultiplier(move.type, player.types) > 1) {
                coveredPlayerTypes.add(player.types.join('/'));
            }
        });
    });
    score += coveredPlayerTypes.size * 13;

    // Costruisce una squadra con ruoli diversi, senza imporre una composizione fissa.
    const chosenRoles = chosenData.map(botTeamRoles);
    if (roles.physical && !chosenRoles.some(role => role.physical)) score += 14;
    if (roles.special && !chosenRoles.some(role => role.special)) score += 14;
    if (roles.utility && !chosenRoles.some(role => role.utility)) score += 10;
    if (roles.fast && !chosenRoles.some(role => role.fast)) score += 7;
    if (roles.durable && !chosenRoles.some(role => role.durable)) score += 7;

    // Il Bot può condividere un Pokémon con il giocatore, ma tende a preferire
    // alternative per rendere le partite meno ripetitive.
    if (playerIndices.includes(candidate.index)) score -= 5;

    return score;
}

function weightedBotTeamPick(candidates) {
    const highest = Math.max(...candidates.map(candidate => candidate.value));
    const weighted = candidates.map(candidate => ({
        entry: candidate,
        // I candidati migliori hanno più probabilità, ma non monopolizzano
        // sempre la scelta. La temperatura mantiene la selezione sensata.
        weight: Math.exp((candidate.value - highest) / 28)
    }));
    const totalWeight = weighted.reduce((sum, item) => sum + item.weight, 0);
    let roll = Math.random() * totalWeight;

    for (const item of weighted) {
        roll -= item.weight;
        if (roll <= 0) return item.entry.candidate;
    }
    return weighted[weighted.length - 1].entry.candidate;
}

function chooseBotTeam(playerIndices=[]) {
    const ranked = RAW_POKEMON_DATA.map((data, index) => ({
        data,
        index,
        score: botTeamValue(data)
    }));

    const chosen = [];
    while (chosen.length < 4 && ranked.length) {
        const available = ranked
            .filter(candidate => !chosen.includes(candidate.index))
            .map(candidate => ({
                candidate,
                value: botTeamCandidateScore(candidate, chosen, playerIndices)
            }))
            .sort((a, b) => b.value - a.value);

        if (!available.length) break;

        // Si considerano i migliori candidati, non tutto il catalogo: la casualità
        // modifica la squadra senza trasformare la scelta in un sorteggio puro.
        const topCandidates = available.slice(0, Math.min(6, available.length));
        const selected = weightedBotTeamPick(topCandidates);
        chosen.push(selected.index);
    }
    return chosen;
}

function botBench(trainerId, except=null) {
    const team = trainerId === 1 ? gameState.p1Team : gameState.p2Team;
    return team.filter(p => !p.isFainted && p.activeSlot === null && p !== except);
}

function botSwitchScore(candidate, enemies) {
    const raw = candidate.originalTypes || candidate.types;
    let score = (candidate.hp / candidate.maxHp) * 32 + (candidate.baseStats.HP + candidate.baseStats.Def + candidate.baseStats.SpD) * 0.12;
    enemies.forEach(enemy => {
        const enemyBest = enemy.moves.reduce((best, move) => {
            if (!move.bp) return best;
            return Math.max(best, typeMultiplier(move.type, raw));
        }, 1);
        const ownBest = candidate.moves.reduce((best, move) => {
            if (!move.bp) return best;
            return Math.max(best, typeMultiplier(move.type, enemy.types));
        }, 1);
        score += (2 - enemyBest) * 28 + (ownBest - 1) * 22;
    });
    if (candidate.status && candidate.status.type) score -= 8;
    return score;
}

function chooseBotSwitch(trainerId, slot=null, candidates=null) {
    const enemies = trainerId === 1 ? enemyActive(1) : enemyActive(2);
    const bench = candidates || botBench(trainerId);
    if (!bench.length) return null;
    return bench
        .map((candidate, index) => ({ candidate, score: botSwitchScore(candidate, enemies), index }))
        .sort((a, b) => b.score - a.score || a.candidate.name.localeCompare(b.candidate.name) || a.index - b.index)[0].candidate;
}

function botMoveTargets(attacker, move) {
    if (move.target !== 'Single Target') return [null];
    const enemies = enemyActive(attacker.trainerId);
    const allies = sideActive(attacker.trainerId).filter(p => p !== attacker);
    if (attacker.v.mustAttackTarget && !attacker.v.mustAttackTarget.isFainted) return [attacker.v.mustAttackTarget];
    if (['Grattini', 'Altini Marito', 'Punto Chill'].includes(move.name)) {
        return [...allies, ...enemies, attacker];
    }
    const redirecting = enemies.find(e => e.v.redirectTurns > 0);
    if (redirecting) return [redirecting];
    return enemies;
}

function botStatusScore(attacker, move, target) {
    const missingHp = 1 - attacker.hp / attacker.maxHp;
    const currentStages = Object.values(attacker.stages).reduce((sum, value) => sum + value, 0);
    const targetStages = target ? Object.values(target.stages).reduce((sum, value) => sum + value, 0) : 0;
    const healingMoves = ['Birra', 'Riposino', 'Heal Full', 'Bibitone', 'Accudire'];
    const setupMoves = ['Anguria Drum', 'Argomentazione', 'Posing', 'Shadow Boxing', 'Low Cortisol', 'Kart', 'Reginetta'];

    if (healingMoves.includes(move.name)) return missingHp * 110 - (attacker.v.da ? 45 : 0);
    if (setupMoves.includes(move.name)) return currentStages < 3 && attacker.hp / attacker.maxHp > 0.45 ? 54 - currentStages * 5 : 8;
    if (move.name === 'Pausa Siga') return botBench(attacker.trainerId, attacker).length ? (missingHp * 55 + 24) : -100;
    if (move.name === 'Sorriso' || move.name === 'Protect') return attacker.hp / attacker.maxHp < 0.35 ? 60 : 15;
    if (move.name === 'Prenotata') return target && target.v.lastMoveUsed ? 48 : 12;
    if (move.name === 'Punto Chill') {
        if (!target || target === attacker) return 28;
        return target.trainerId === attacker.trainerId ? (targetStages > 0 ? 62 : 24) : (targetStages < 0 ? 12 : 48);
    }
    if (target && target.trainerId !== attacker.trainerId) {
        let score = target.status.type ? 12 : 30;
        if (move.effect === 'stat_down_atk_spa' || move.effect === 'cucciolone' || move.effect === 'rutto_effect') score += targetStages > 0 ? 22 : 8;
        return score;
    }
    return 18;
}

function botActionScore(attacker, move, target) {
    if (move.effect === 'all_in') {
        if (!target) return -1000;
        return target.hp / target.maxHp < 0.55 ? 190 : 42;
    }
    if (!move.bp) return botStatusScore(attacker, move, target);

    const targets = move.target === 'All Opponents' ? enemyActive(attacker.trainerId)
        : move.target === 'All Pokemon' ? allPokemonTargets(attacker)
        : move.target === 'All Allies' ? sideActive(attacker.trainerId)
        : move.target === 'Self' ? [attacker]
        : [target].filter(Boolean);
    if (!targets.length) return -1000;

    let score = 0;
    targets.forEach(defender => {
        const result = computeDamage(attacker, defender, move, { isCrit: move.effect === 'crit_always', numTargets: targets.length });
        if (!result || result.tMod === 0) {
            score -= 30;
            return;
        }
        const expectedDamage = result.dmg * ((move.accuracy == null ? 100 : move.accuracy) / 100);
        score += expectedDamage + (result.tMod > 1 ? 30 * result.tMod : 0);
        if (result.dmg >= defender.hp) score += 100;
        if (defender.v.protectedThisTurn) score -= 20;
    });
    if (move.priority) score += move.priority * 4;
    if (move.target === 'All Opponents') score += 18;
    if (move.effect === 'recoil_33') score -= attacker.hp / attacker.maxHp < 0.35 ? 32 : 0;
    return score;
}

function botBestAction(attacker) {
    const legalMoves = attacker.moves.filter(move => {
        const locked = attacker.v.moveLockout[move.name] > 0;
        const giaLocked = attacker.ability === 'Ottimizzazione' &&
            move.category !== 'Stato' &&
            attacker.v.giaLastDamagingRound === gameState.roundNumber;
        return !locked && !giaLocked;
    });

    let best = null;
    legalMoves.forEach((move, moveIndex) => {
        botMoveTargets(attacker, move).forEach((target, targetIndex) => {
            const score = botActionScore(attacker, move, target);
            if (!best || score > best.score ||
                (score === best.score && (moveIndex < best.moveIndex ||
                    (moveIndex === best.moveIndex && targetIndex < best.targetIndex)))) {
                best = { type: 'move', move, target, score, moveIndex, targetIndex };
            }
        });
    });
    return best;
}

function botShouldSwitch(attacker) {
    if (!attacker || attacker.v.trapped || attacker.v.frozenAtkNoLeave) return false;
    const bench = botBench(attacker.trainerId, attacker);
    if (!bench.length) return false;
    const hpRatio = attacker.hp / attacker.maxHp;
    if (hpRatio <= 0.22) return true;
    if (hpRatio > 0.42) return false;
    const enemies = enemyActive(attacker.trainerId);
    const currentThreat = enemies.reduce((sum, enemy) => sum + enemy.moves.reduce((best, move) => {
        return move.bp ? Math.max(best, typeMultiplier(move.type, attacker.types)) : best;
    }, 1), 0);
    const bestBench = Math.max(...bench.map(candidate => botSwitchScore(candidate, enemies)));
    return currentThreat >= 3 && bestBench > botSwitchScore(attacker, enemies) + 12;
}

function botPromptNextMove() {
    const activePoke = gameState.p2Active[currentSlotTurn];
    document.getElementById("controls-area").innerHTML = `<div style="grid-column:1 / -1; text-align:center;"><h4>Il Bot sta scegliendo...</h4></div>`;
    if (!activePoke || activePoke.isFainted) { advanceActor(); return; }

    if (activePoke.v.forcedMove && activePoke.v.forcedMove.turnsLeft > 0) {
        const forced = activePoke.moves.find(move => move.name === activePoke.v.forcedMove.name);
        if (forced) {
            printLog(`🔁 ${pname(activePoke)} è costretto a ripetere ${forced.name}!`);
            queueAction(activePoke, forced, defaultTargetFor(activePoke, forced));
            activePoke.v.forcedMove.turnsLeft--;
            advanceActor();
            return;
        }
    }

    const action = botBestAction(activePoke);
    if (botShouldSwitch(activePoke)) {
        const replacement = chooseBotSwitch(2, currentSlotTurn);
        if (replacement) {
            printLog(`🔄 Il Bot valuta il campo e cambia ${pname(activePoke)} con ${replacement.name}.`);
            queueSwitchAction(2, currentSlotTurn, activePoke, replacement);
            return;
        }
    }
    if (action && action.score > -500) {
        queueAction(activePoke, action.move, action.target);
        advanceActor();
        return;
    }
    queueAction(activePoke, { name:"Attesa", type:"Puro", category:"Stato", bp:0, target:"Self" }, activePoke);
    advanceActor();
}

function defaultTargetFor(attacker, move) {
    if (move.target === 'Self' || move.target === 'All Allies' || move.target === 'All Opponents' || move.target === 'All Pokemon') return null;
    const enemies = enemyActive(attacker.trainerId);
    if (attacker.v.mustAttackTarget && !attacker.v.mustAttackTarget.isFainted) return attacker.v.mustAttackTarget;
    const redirecting = enemies.find(e => e.v.redirectTurns > 0);
    if (redirecting) return redirecting;
    return enemies[0] || null;
}

function onMoveChosen(attacker, move) {
    const enemies = enemyActive(attacker.trainerId);
    const allies = sideActive(attacker.trainerId).filter(p => p !== attacker);
    let targetOptions = [];

    if (move.target === 'Single Target') {
        // Ogni mossa a bersaglio singolo può ora scegliere anche un alleato in campo.
        // Le mosse già abilitate a colpire sé stessi mantengono questa possibilità.
        const canTargetSelf = ['Grattini', 'Altini Marito', 'Punto Chill'].includes(move.name);
        const candidates = attacker.v.mustAttackTarget && !attacker.v.mustAttackTarget.isFainted
            ? [attacker.v.mustAttackTarget]
            : [...allies, ...enemies, ...(canTargetSelf ? [attacker] : [])];

        // Abilità/effetti di reindirizzamento continuano a prevalere sulla scelta manuale,
        // ma il menu viene comunque mostrato per permettere di deselezionare la mossa.
        const redirecting = candidates.find(e => e.v.redirectTurns > 0 && enemies.includes(e));
        targetOptions = (redirecting ? [redirecting] : candidates).map(target => ({
            label: `${target.name} (${target.trainerId === attacker.trainerId
                ? (target === attacker ? 'sé stesso' : 'alleato')
                : 'avversario'})`,
            onClick: () => { queueAction(attacker, move, target); advanceActor(); }
        }));
    } else if (move.target === 'Self') {
        targetOptions = [{
            label: `${attacker.name} (sé stesso)`,
            // Per mantenere invariata la risoluzione delle mosse Self, il bersaglio
            // effettivo resta null come nel comportamento precedente.
            onClick: () => { queueAction(attacker, move, null); advanceActor(); }
        }];
    } else if (move.target === 'All Allies') {
        targetOptions = [{
            label: 'Tutti gli alleati',
            onClick: () => { queueAction(attacker, move, null); advanceActor(); }
        }];
    } else if (move.target === 'All Opponents') {
        targetOptions = [{
            label: 'Tutti gli avversari',
            onClick: () => { queueAction(attacker, move, null); advanceActor(); }
        }];
    } else if (move.target === 'All Pokemon') {
        targetOptions = [{
            label: 'Tutti',
            onClick: () => { queueAction(attacker, move, null); advanceActor(); }
        }];
    } else {
        // Fallback per eventuali categorie future: conserva il comportamento precedente.
        targetOptions = [{
            label: 'Conferma mossa',
            onClick: () => { queueAction(attacker, move, defaultTargetFor(attacker, move)); advanceActor(); }
        }];
    }

    // La mossa non viene ancora messa in coda: il giocatore può sempre tornare
    // alla griglia e sceglierne un'altra per il Pokémon corrente.
    targetOptions.push({
        label: '↩ Deseleziona mossa',
        onClick: () => promptNextMove()
    });
    showModal(`${attacker.name}: scegli bersaglio per ${move.name}`, targetOptions);
}

function queueAction(actor, move, target) {
    // Registriamo anche slot/trainer originali del bersaglio: se nel frattempo (per uno switch
    // manuale avvenuto in fase di selezione, o per Pausa Siga durante l'esecuzione) qualcun altro
    // prende il suo posto, la mossa dovrà colpire chi si trova ORA in quello slot, non l'oggetto
    // Pokémon scelto al momento della selezione.
    const targetInfo = target ? { trainerId: target.trainerId, slot: target.activeSlot } : null;
    roundActions.push({ type:'move', trainer: actor.trainerId, slot: actor.activeSlot, actor, move, target, targetInfo });
}

function skipTurn() {
    let activePoke = currentTrainerTurn===1 ? gameState.p1Active[currentSlotTurn] : gameState.p2Active[currentSlotTurn];
    if (!activePoke) { advanceActor(); return; }
    queueAction(activePoke, { name:"Attesa", type:"Puro", category:"Stato", bp:0, target:"Self" }, activePoke);
    advanceActor();
}

function quitBattle() {
    const root = document.getElementById("modal-root");
    root.innerHTML = `<div class="modal-overlay"><div class="modal-box pass-device-box">
        <h3>Abbandonare la battaglia?</h3>
        <p>La partita corrente verrà annullata e tornerai alla scelta della modalità.</p>
        <div id="quit-battle-btn-holder"></div>
    </div></div>`;

    const holder = document.getElementById("quit-battle-btn-holder");
    const quitBtn = document.createElement("button");
    quitBtn.innerText = "Sì, abbandona";
    quitBtn.style.background = "#e74c3c";
    quitBtn.onclick = () => {
        root.innerHTML = "";
        resetGame();
    };

    const cancelBtn = document.createElement("button");
    cancelBtn.innerText = "Annulla";
    cancelBtn.style.background = "#7f8c8d";
    cancelBtn.onclick = () => closeModal();

    holder.appendChild(quitBtn);
    holder.appendChild(cancelBtn);
}

function advanceActor() {
    currentSlotTurn++;
    if (currentSlotTurn > 1) {
        currentSlotTurn = 0;
        if (currentTrainerTurn === 1) {
            currentTrainerTurn = 2;
            // Nella modalità Bot il secondo allenatore seleziona le azioni senza popup.
            if (isBotMode()) promptNextMove();
            else showPassDevice(2, () => promptNextMove());
        }
        else { currentTrainerTurn = 1; executeTurnQueue(); }
    } else {
        promptNextMove();
    }
}

/* =========================================================================
   CAMBIO POKEMON
   ========================================================================= */
function openSwitchMenu() {
    const trainerId = currentTrainerTurn;
    const bench = (trainerId===1?gameState.p1Team:gameState.p2Team).filter(p=>!p.isFainted && p.activeSlot===null);
    const activePoke = trainerId===1?gameState.p1Active[currentSlotTurn]:gameState.p2Active[currentSlotTurn];
    if (activePoke && activePoke.v.trapped) { printLog(`🚫 ${pname(activePoke)} non può lasciare il campo!`); return; }
    if (bench.length === 0) { printLog("Nessun Pokémon disponibile per il cambio."); return; }
    showModal(`Cambia con:`, bench.map(b => ({
        label: `${b.name} (HP ${b.hp}/${b.maxHp})`,
        onClick: () => queueSwitchAction(trainerId, currentSlotTurn, activePoke, b)
    })));
}

// Mette in coda uno switch "posticipato": la scelta viene registrata (senza eseguirla né
// loggarla) esattamente come farebbe una mossa, e verrà risolta solo all'inizio
// dell'esecuzione del turno, con priorità sempre massima rispetto a qualunque mossa.
function queueSwitchAction(trainerId, slot, actor, newPoke) {
    roundActions.push({ type:'switch', trainer: trainerId, slot, actor, newPoke });
    advanceActor();
}

// Esegue lo scambio "meccanico" (chi esce/chi entra + abilità d'ingresso + refresh UI)
// senza toccare il flusso di selezione/esecuzione del turno. Va usato ogni volta che
// uno scambio avviene DENTRO l'esecuzione di una mossa (Pausa Siga, Subito a Casa!, ecc.),
// durante la risoluzione degli switch manuali posticipati a inizio turno, o durante la
// risoluzione di uno switch forzato per KO.
function directSwitchIn(trainerId, slot, newPoke) {
    const active = trainerId===1?gameState.p1Active:gameState.p2Active;
    const old = active[slot];
    if (old) old.resetOnSwitchOut();
    active[slot] = newPoke;
    newPoke.activeSlot = slot;
    printLog(`🔄 ${trainerId === 2 && isBotMode() ? "Il Bot" : `Giocatore ${trainerId}`} manda in campo ${newPoke.name}!`);
    triggerEntryAbility(newPoke);
    updateUI();
}

/* =========================================================================
   ESECUZIONE TURNO
   ========================================================================= */
function movePriority(action) {
    let p = action.move.priority || 0;
    if (action.move.effect === 'cannata' && action.target && action.target.ability === 'Scopiamo') p = 4;
    return p;
}

function executeTurnQueue() {
    printLog("<br>--- <b>INIZIO TURNO</b> ---");
    gameState.roundNumber++;

    // Le mosse di protezione (Sorriso/Balzata ecc.) devono proteggere SOLO durante il
    // turno in cui sono state usate, senza alcun effetto residuo in quelli successivi.
    // Azzeriamo quindi i flag di protezione per TUTTI gli attivi all'inizio di ogni
    // nuovo turno, invece di farlo solo quando il singolo Pokémon torna ad agire: in
    // questo modo casi come sonno/gelo/confusione che gli impediscono di muoversi, o un
    // tentennamento (flinch) che salta del tutto la sua azione, non lasciano la vecchia
    // protezione attiva "a scrocco" nel turno seguente.
    allActive().forEach(p => {
        p.v.protectedThisTurn = false;
        p.v.protectedFromMalesThisTurn = false;
    });

    // Gli switch manuali posticipati hanno SEMPRE priorità massima: vengono risolti
    // tutti, per entrambi i giocatori, prima di qualunque mossa (incluse quelle a
    // priorità +3 come Sorriso/Balzata). Vengono eseguiti nell'ordine in cui sono
    // stati scelti durante la selezione.
    const switchActions = roundActions.filter(a => a.type === 'switch');
    const moveActions = roundActions.filter(a => a.type !== 'switch');

    switchActions.forEach(a => {
        const active = a.trainer===1?gameState.p1Active:gameState.p2Active;
        if (a.actor.isFainted) return; // sicurezza: non dovrebbe accadere in questa fase
        if (active[a.slot] !== a.actor) return; // lo slot è già stato modificato in modo imprevisto
        if (a.newPoke.isFainted || a.newPoke.activeSlot !== null) return; // il sostituto non è più disponibile
        directSwitchIn(a.trainer, a.slot, a.newPoke);
    });

    roundActions = moveActions;

    // A parità di priority e velocità, assegniamo un sorteggio stabile per tutta
    // la risoluzione del turno. In questo modo l'ordine è uniforme tra i Pokémon
    // in parità senza usare un comparatore casuale, che potrebbe produrre ordini
    // non uniformi durante i confronti interni di Array.sort().
    const tieGroups = new Map();
    moveActions.forEach(action => {
        const key = `${movePriority(action)}|${getStat(action.actor,'Spe')}`;
        if (!tieGroups.has(key)) tieGroups.set(key, []);
        tieGroups.get(key).push(action);
    });
    const tieBreakers = new Map();
    tieGroups.forEach(group => {
        if (group.length > 1) group.forEach(action => tieBreakers.set(action, Math.random()));
    });

    roundActions.sort((a,b) => {
        let pa = movePriority(a), pb = movePriority(b);
        if (pa !== pb) return pb - pa;
        const speedDifference = getStat(b.actor,'Spe') - getStat(a.actor,'Spe');
        if (speedDifference !== 0) return speedDifference;
        return (tieBreakers.get(a) || 0) - (tieBreakers.get(b) || 0);
    });

    // Fermii: se è la prima mossa in ordine di priorità di chi la usa ed è la prima volta che agisce, fa flinchare chi deve ancora muoversi
    const flinched = new Set();
    processQueuedAction(0, flinched);
}

// Processa le azioni della coda una alla volta, in sequenza. Alcune mosse (es. Pausa
// Siga) richiedono che il giocatore scelga qualcosa a metà dell'esecuzione: in quel
// caso l'azione corrente "mette in pausa" la coda e la richiama da sola (tramite il
// callback onComplete passato a executeSingleAction/runMoveEffect) solo dopo che la
// scelta è stata fatta, così l'ordine delle azioni successive resta corretto.
function processQueuedAction(idx, flinched) {
    if (idx >= roundActions.length) {
        endOfRoundEffects();
        return;
    }
    const action = roundActions[idx];
    const proceed = () => processQueuedAction(idx + 1, flinched);

    if (action.actor.isFainted) { proceed(); return; }
    if (flinched.has(action.actor)) { printLog(`😵 ${pname(action.actor)} tentenna e non può muoversi!`); proceed(); return; }

    // Risolve il bersaglio "live": se lo slot originale ora è occupato da un Pokémon diverso
    // (switch manuale posticipato o Pausa Siga avvenuti prima/durante l'esecuzione), la mossa
    // segue il nuovo occupante. Se invece lo slot è vuoto (il bersaglio è andato KO e non è
    // ancora stato sostituito), manteniamo l'oggetto originale così la logica più sotto in
    // executeSingleAction può correttamente reindirizzare verso un eventuale alleato.
    let liveTarget = action.target;
    if (action.targetInfo) {
        const arr = action.targetInfo.trainerId === 1 ? gameState.p1Active : gameState.p2Active;
        const current = arr[action.targetInfo.slot];
        if (current) liveTarget = current;
    }

    executeSingleAction(action.actor, liveTarget, action.move, flinched, () => {
        if (checkWinner()) return;
        proceed();
    });
}

function isProtected(defender, attacker, move) {
    if (defender.v.protectedThisTurn && move.category !== 'Stato') return true;
    if (defender.v.protectedFromMalesThisTurn && attacker.gender === 'Maschio') return true;
    return false;
}

function executeSingleAction(attacker, defender, move, flinchedSet, onComplete) {
    onComplete = onComplete || function(){};

    if (attacker.status.type === 'Sleep') {
        attacker.status.sleepTurns++;
        if (attacker.status.sleepTurns >= 3 || (attacker.status.sleepTurns===2 && Math.random()<0.5)) {
            attacker.status = {type:null,counter:0,sleepTurns:0};
            printLog(`😴 ${pname(attacker)} si sveglia!`);
        } else { printLog(`😴 ${pname(attacker)} dorme ancora.`); onComplete(); return; }
    }
    if (attacker.status.type === 'Frozen') {
        if (Math.random() < 0.5) { attacker.status = {type:null,counter:0,sleepTurns:0}; printLog(`🧊 ${pname(attacker)} si libera dal gelo!`); }
        else { printLog(`🧊 ${pname(attacker)} è congelato e non può muoversi!`); onComplete(); return; }
    }
    if (attacker.v.confused) {
        const escapeChance = gameState.field.terreno === 'Alcol' ? 0.125 : 0.25;
        if (Math.random() < escapeChance) { attacker.v.confused = false; printLog(`💫 ${pname(attacker)} non è più confuso.`); }
        else if (Math.random() < 0.33) {
            // La confusione ha il 33% di probabilità di impedire la mossa e far colpire se stessi
            const selfDmg = Math.max(1, Math.floor(attacker.maxHp * 0.08));
            attacker.hp = Math.max(0, attacker.hp - selfDmg);
            printLog(`💫 ${pname(attacker)} è confuso e si colpisce da solo (${selfDmg} danni)!`);
            if (attacker.hp === 0) { attacker.isFainted = true; printLog(`💀 ${pname(attacker)} è andato KO!`); handleFaint(attacker); }
            onComplete(); return;
        }
    }

    // Ottimizzazione: blocco di sicurezza nel caso una mossa offensiva venga forzata
    // (es. ripetizione forzata) nel turno immediatamente successivo a un'altra mossa offensiva.
    if (attacker.ability === 'Ottimizzazione' && move.category !== 'Stato' && attacker.v.giaLastDamagingRound === gameState.roundNumber - 1) {
        printLog(`🚫 ${pname(attacker)} non può usare mosse che infliggono danno per due turni consecutivi!`);
        onComplete(); return;
    }

    // (I flag di protezione vengono ora azzerati centralmente a inizio turno in
    // executeTurnQueue, per coprire correttamente anche i casi in cui l'attaccante non
    // riesce ad agire questo turno: vedi commento lì.)
    attacker.v.lastMoveUsed = move.name;
    attacker.v.hasActedOnce = true;

    if (move.effect === 'fermii_flinch') {
        if (attacker.v.hadFirstMoveUsed) { printLog(`${pname(attacker)} non può usare Fermii se non come prima mossa in assoluto!`); }
        else {
            attacker.v.hadFirstMoveUsed = true;
            enemyActive(attacker.trainerId).forEach(e => flinchedSet.add(e));
            printLog(`💨 ${pname(attacker)} usa Fermii! Gli avversari che devono ancora muoversi tentennano!`);
        }
        onComplete(); return;
    }
    attacker.v.hadFirstMoveUsed = true;

    if (defender && defender.isFainted) {
        const ally = sideActive(defender.trainerId).find(p=>p!==defender);
        if (!ally) { printLog(`${move.name} fallisce: nessun bersaglio disponibile.`); onComplete(); return; }
        defender = ally;
    }

    printLog(`▶️ <b>${pname(attacker)}</b> usa <b>${move.name}</b>!`);

    if (attacker.ability === 'Ottimizzazione' && move.category !== 'Stato') {
        attacker.v.giaLastDamagingRound = gameState.roundNumber;
    }

    // All in: gestita interamente qui perché è una mossa a BP 0 non di Stato che deve
    // mettere KO il bersaglio se va a segno, o l'attaccante stesso (Matte Iliev) se fallisce.
    if (move.effect === 'all_in') {
        if (!defender) { printLog(`${move.name} fallisce: nessun bersaglio disponibile.`); onComplete(); return; }
        if (isProtected(defender, attacker, move)) {
            printLog(`🛡️ ${pname(defender)} si protegge dall'attacco!`);
            onComplete(); return;
        }
        if (checkAccuracy(attacker, defender, move)) {
            defender.hp = 0; defender.isFainted = true;
            printLog(`💥 All in va a segno! ${pname(defender)} va KO!`);
            handleFaint(defender);
        } else {
            attacker.hp = 0; attacker.isFainted = true;
            printLog(`💥 All in fallisce! ${pname(attacker)} va KO!`);
            handleFaint(attacker);
        }
        onComplete();
        return;
    }

    // Cannata!!! ignora qualsiasi protezione se il bersaglio ha l'abilità Scopiamo
    const cannataBypass = move.effect === 'cannata' && defender && defender.ability === 'Scopiamo';

    if (defender && move.target === 'Single Target' && !cannataBypass && isProtected(defender, attacker, move)) {
        printLog(`🛡️ ${pname(defender)} si protegge dall'attacco!`);
        onComplete(); return;
    }

    const isMultiTargetMove = ['All Opponents', 'All Pokemon', 'All Allies'].includes(move.target);
    if (move.target === 'Single Target' && move.category !== 'Stato') {
        if (!checkAccuracy(attacker, defender, move)) { printLog(`❌ ${move.name} non va a segno!`); onComplete(); return; }
    } else if (move.accuracy != null && !isMultiTargetMove) {
        if (!checkAccuracy(attacker, defender || attacker, move)) {
            printLog(`❌ ${move.name} non va a segno!`);
            runMoveEffect(move, attacker, defender, { failed:true }, onComplete);
            return;
        }
    }

    // Cannata!!! diventa OHKO contro pokemon con abilità Scopiamo (già garantito di andare a
    // segno dal controllo di accuracy sopra, e di ignorare Protect dal controllo sopra).
    if (move.effect === 'cannata' && defender && defender.ability === 'Scopiamo') {
        printLog(`🎤 Cannata!!! trapassa ogni protezione e mette KO ${pname(defender)} all'istante (Scopiamo)!`);
        defender.hp = 0; defender.isFainted = true;
        printLog(`💀 <b>${pname(defender)} è andato KO!</b>`);
        runMoveEffect(move, attacker, defender, { targets:[defender], totalDamage: defender.maxHp }, () => {
            if (defender.isFainted) handleFaint(defender);
            if (attacker.isFainted) handleFaint(attacker);
            onComplete();
        });
        return;
    }

    if (move.category === 'Stato' && move.bp === 0) {
        if (isMultiTargetMove && move.accuracy != null) {
            const statusTargets = move.target === 'All Opponents' ? enemyActive(attacker.trainerId)
                : move.target === 'All Pokemon' ? allPokemonTargets(attacker)
                : move.target === 'All Allies' ? sideActive(attacker.trainerId)
                : [];
            const successfulTargets = statusTargets.filter(target => {
                if (target.isFainted) return false;
                if (!checkAccuracy(attacker, target, move)) {
                    printLog(`❌ ${move.name} non va a segno su ${pname(target)}!`);
                    return false;
                }
                if (target !== attacker && isProtected(target, attacker, move)) {
                    printLog(`🛡️ ${pname(target)} si protegge!`);
                    return false;
                }
                return true;
            });
            runMoveEffect(move, attacker, defender, { targets: statusTargets, successfulTargets }, onComplete);
        } else {
            runMoveEffect(move, attacker, defender, {}, onComplete);
        }
        return;
    }

    // determina bersagli multipli
    let targets = [];
    if (move.target === 'Single Target') targets = [defender].filter(Boolean);
    else if (move.target === 'All Opponents') targets = enemyActive(attacker.trainerId);
    else if (move.target === 'All Pokemon') targets = allPokemonTargets(attacker);
    else if (move.target === 'All Allies') targets = sideActive(attacker.trainerId);
    else if (move.target === 'Self') targets = [attacker];

    const isCrit = move.effect === 'crit_always';
    let totalDamage = 0;
    const successfulTargets = [];
    targets.forEach(t => {
        if (t.isFainted) return;
        if (move.accuracy != null && !checkAccuracy(attacker, t, move)) {
            printLog(`❌ ${move.name} non va a segno su ${pname(t)}!`);
            return;
        }
        if (t !== attacker && isProtected(t, attacker, move)) { printLog(`🛡️ ${pname(t)} si protegge!`); return; }
        successfulTargets.push(t);
        const { dmg, tMod } = computeDamage(attacker, t, move, { isCrit, numTargets: targets.length });
        if (tMod === 0) { printLog(`🚫 Non ha effetto su ${pname(t)}.`); return; }
        // Recoil: contiamo solo gli HP EFFETTIVAMENTE sottratti (capped a 0), non il danno
        // teorico della mossa. Se il colpo manda KO con meno danno di quello calcolato,
        // il contraccolpo successivo si baserà solo sulla parte realmente inflitta.
        const hpBefore = t.hp;
        t.hp = Math.max(0, t.hp - dmg);
        const actualDamage = hpBefore - t.hp;
        totalDamage += actualDamage;
        printLog(`💥 ${pname(t)} subisce ${actualDamage} danni!` + (tMod>1?' 🔺 Superefficace!':tMod<1?' 🔻 Poco efficace...':''));
        if (t.hp === 0) { t.isFainted = true; printLog(`💀 <b>${pname(t)} è andato KO!</b>`); }
    });

    if (move.effect === 'recoil_33' && totalDamage > 0) {
        const recoil = Math.floor(totalDamage * 0.33);
        attacker.hp = Math.max(0, attacker.hp - recoil);
        printLog(`💢 ${pname(attacker)} subisce ${recoil} danni di contraccolpo!`);
        if (attacker.hp === 0) { attacker.isFainted = true; printLog(`💀 ${pname(attacker)} è andato KO per il contraccolpo!`); }
    }

    runMoveEffect(move, attacker, defender, { targets, successfulTargets, totalDamage }, () => {
        targets.forEach(t => { if (t.isFainted) handleFaint(t); });
        if (attacker.isFainted) handleFaint(attacker);
        onComplete();
    });
}

function handleFaint(poke) {
    poke.resetOnSwitchOut();
    poke.activeSlot = null;
    const active = poke.trainerId===1?gameState.p1Active:gameState.p2Active;
    const idx = active.indexOf(poke);
    if (idx !== -1) active[idx] = null;
}

// I danni da stato/clima a fine turno marcano isFainted=true ma non passano da handleFaint():
// questa funzione va chiamata subito dopo per svuotare davvero lo slot di chi è appena
// andato KO in quel modo, altrimenti la coda delle sostituzioni forzate non se ne accorge.
function clearFaintedActiveSlots() {
    [...gameState.p1Active, ...gameState.p2Active].forEach(p => {
        if (p && p.isFainted) handleFaint(p);
    });
}

/* =========================================================================
   EFFETTI DELLE MOSSE
   ========================================================================= */
function runMoveEffect(move, attacker, defender, ctx, onComplete) {
    onComplete = onComplete || function(){};
    const eff = move.effect;
    if (!eff) { onComplete(); return; }
    const enemies = enemyActive(attacker.trainerId);
    const allies = sideActive(attacker.trainerId);
    const allPokemonEffectTargets = ctx.successfulTargets || allPokemonTargets(attacker);

    switch (eff) {
        case 'hyper_poison':
            enemyActive(attacker.trainerId).forEach(e => tryInflictStatus(e, 'Iperavvelenato'));
            break;
        case 'hyper_poison_single':
            if (defender) tryInflictStatus(defender, 'Iperavvelenato');
            break;
        case 'protect_and_terrain_chill':
            handleProtect(attacker, 'all');
            setTerreno('Chill', attacker);
            break;
        case 'protect_self':
            handleProtect(attacker, 'all');
            break;
        case 'stat_down_atk_spa':
            if (defender) changeStage(defender, {Atk:-1, SpA:-1});
            break;
        case 'fungo_status':
            if (defender) tryInflictStatus(defender, 'Fungo');
            break;
        case 'anguria_drum':
            attacker.hp = Math.max(1, Math.floor(attacker.hp/2));
            attacker.stages.Atk = 6;
            printLog(`🍉 ${pname(attacker)} dimezza i propri HP e massimizza l'Attacco!`);
            break;
        case 'birra_heal':
            healPoke(attacker, 1.0);
            attacker.v.accuracyPenalty = (attacker.v.accuracyPenalty||0) + 50;
            printLog(`🍺 ${pname(attacker)} recupera tutta la vita ma perde precisione!`);
            break;
        case 'medusa_effect':
            allActive().forEach(p => tryInflictStatus(p, 'Confuso'));
            if (defender) changeStage(defender, {Def:-1, SpD:-1});
            break;
        case 'recoil_33': break; // gestito sopra
        case 'drift_effect':
            if (ctx.failed) { attacker.hp = Math.max(0, attacker.hp - Math.floor(attacker.maxHp/3)); printLog(`💨 Drift fallisce, ${pname(attacker)} perde 1/3 HP!`); if(attacker.hp===0){attacker.isFainted=true; handleFaint(attacker);} }
            else { changeStage(attacker, {Spe:6}); setClima('Fumo', attacker); }
            break;
        case 'rutto_effect':
            if (defender) changeStage(defender, {Atk:-1});
            break;
        case 'punto_chill':
            if (!defender || defender === attacker) changeStage(attacker, {Def:1, SpD:1, Spe:-1});
            else if (defender.trainerId === attacker.trainerId) changeStage(defender, {Atk:1, SpA:1, Def:1, SpD:1});
            else changeStage(defender, {Atk:-1, SpA:-1, Def:-1, SpD:-1});
            break;
        case 'da_status':
            enemyActive(attacker.trainerId).forEach(e => { e.v.da = true; });
            printLog(`🍽️ Gli avversari colpiti ricevono stato DA!`);
            break;
        case 'pausa_siga': {
            if (attacker.v.moveLockout['Pausa Siga'] > 0) { printLog(`${pname(attacker)} non può ancora ripetere Pausa Siga!`); break; }
            const bench = (attacker.trainerId===1?gameState.p1Team:gameState.p2Team).filter(p=>!p.isFainted && p !== attacker && p.activeSlot===null);
            if (bench.length === 0) { printLog(`Pausa Siga fallisce: nessun alleato disponibile!`); break; }

            setClima('Fumo', attacker);
            const slot = attacker.activeSlot;
            const trainerId = attacker.trainerId;

            // segna che questo Pokémon dovrà rientrare automaticamente a fine turno
            gameState.pendingReturn = gameState.pendingReturn || [];
            gameState.pendingReturn.push({ poke: attacker, slot, trainerId });

            printLog(`🚬 ${pname(attacker)} esce per una pausa sigaretta! Rientrerà a fine turno.`);
            if (isBotMode() && trainerId === 2) {
                const replacement = chooseBotSwitch(trainerId, slot, bench);
                if (replacement) {
                    directSwitchIn(trainerId, slot, replacement);
                    // Il lockout viene impostato dopo lo switch perché il reset del Pokémon
                    // uscito azzera i contatori temporanei.
                    attacker.v.moveLockout['Pausa Siga'] = 2;
                    onComplete();
                    return;
                }
            }
            showModal(`Chi mandi in campo al posto di ${attacker.name}?`, bench.map(b => ({
                label: `${b.name} (HP ${b.hp}/${b.maxHp})`,
                onClick: () => {
                    directSwitchIn(trainerId, slot, b);
                    // Il lockout va impostato DOPO lo switch: resetOnSwitchOut() (chiamato da
                    // directSwitchIn su chi esce) azzera v.moveLockout, quindi se lo impostassimo
                    // prima verrebbe cancellato immediatamente.
                    attacker.v.moveLockout['Pausa Siga'] = 2;
                    onComplete();
                }
            })));
            return; // l'esecuzione riprende solo dopo la scelta del giocatore nel modale
        }
        case 'argomentazione':
            changeStage(attacker, {Def:1, SpD:1});
            break;
        case 'posing':
            changeStage(attacker, {Atk:2, Def:2, Spe:-1});
            break;
        case 'burn_status':
            (move.target==='All Pokemon'?allPokemonEffectTargets:enemyActive(attacker.trainerId)).forEach(t => tryInflictStatus(t, 'Burn'));
            break;
        case 'burn_status_single':
            if (defender) tryInflictStatus(defender, 'Burn');
            break;
        case 'squalo_limone':
            changeStage(attacker, {Spe:1});
            break;
        case 'cucciolone':
            if (defender) changeStage(defender, {Def:-1, SpD:-1, Spe:-1});
            break;
        case 'gold_rain':
            changeStage(attacker, {SpA:-1});
            break;
        case 'shadow_boxing':
            changeStage(attacker, {Atk:1, Def:1});
            break;
        case 'pugni_merda':
            changeStage(attacker, {Def:-1, SpD:-1});
            break;
        case 'bomba_acqua':
            changeStage(attacker, {Atk:-1, SpA:-1, Def:-1, SpD:-1, Spe:-1});
            break;
        case 'crit_always': break; // gestito nel calcolo danno
        case 'viva_il_duce': break; // BP dinamico gestito in getEffectiveBp (vedi sotto)
        case 'squarta_neri': break; // moltiplicatore gestito in computeDamage extra (vedi sotto)
        case 'accudire':
            allies.forEach(a => { healPoke(a, 0.2); a.status = {type:null,counter:0,sleepTurns:0}; a.v.fungo=false; a.v.da=false; a.v.confused=false; });
            break;
        case 'baffetto':
            attacker.gender = 'Maschio';
            enemyActive(attacker.trainerId).filter(e=>e.gender==='Maschio').forEach(e => changeStage(e, {Atk:-1}));
            break;
        case 'reginetta':
            allies.filter(a=>a.gender==='Femmina').forEach(a => changeStage(a, {Atk:1, SpA:1, SpD:1, Def:1}));
            break;
        case 'svenimento':
            attacker.hp = Math.max(1, Math.floor(attacker.hp/2));
            attacker.v.redirectTurns = 3;
            printLog(`🎯 Gli avversari saranno costretti a colpire ${pname(attacker)} per 3 turni!`);
            break;
        case 'calcio_balcanico':
            if (defender && Math.random() < 0.3) changeStage(defender, {Def:-1});
            break;
        case 'riposino':
            healPoke(attacker, 1.0);
            attacker.status = { type:'Sleep', counter:0, sleepTurns:0 };
            printLog(`😴 ${pname(attacker)} recupera tutti gli HP ma si addormenta!`);
            break;
        case 'multi_hit': break; // gestito con hit multipli extra nel wrapper sotto
        case 'prenotata':
            if (defender) {
                let mv;
                if (isBotMode() && attacker.trainerId === 2) {
                    mv = defender.moves
                        .map((candidate, index) => ({ candidate, index, score: botActionScore(defender, candidate, defaultTargetFor(defender, candidate)) }))
                        .sort((a, b) => b.score - a.score || a.index - b.index)[0].candidate;
                } else {
                    let choice = window.prompt(`${attacker.name} usa Prenotata su ${defender.name}. Quale mossa di ${defender.name} deve ripetere per 3 turni? (${defender.moves.map(m=>m.name).join(', ')})`, defender.moves[0].name);
                    mv = defender.moves.find(m=>m.name===choice) || defender.moves[0];
                }
                defender.v.forcedMove = { name: mv.name, turnsLeft: 3 };
                printLog(`🔒 ${pname(defender)} è costretto a ripetere ${mv.name} per 3 turni!`);
            }
            break;
        case 'heal_full':
            healPoke(attacker, 1.0);
            break;
        case 'cannata': break; // OHKO/priorità/bypass-protect gestiti sopra in executeSingleAction/movePriority
        case 'altini_marito':
            if (defender && defender.gender === 'Femmina') { printLog(`Altini Marito fallisce sui Pokemon Femmina.`); break; }
            if (defender && defender.name === 'Altini') changeStage(defender, {Atk:1,SpA:1,Def:1,SpD:1});
            else if (defender) changeStage(defender, {Atk:-1,SpA:-1,Def:-1,SpD:-1});
            break;
        case 'croste':
            if (defender) { tryInflictStatus(defender, 'Frozen'); defender.v.frozenAtkNoLeave = attacker; defender.v.trapped = true; }
            break;
        case 'nuvole':
            if (defender) tryInflictStatus(defender, 'Confuso');
            break;
        case 'low_cortisol':
            changeStage(attacker, {Spe:-1, SpD:1, Def:1});
            break;
        case 'trap_target':
            if (defender) defender.v.trapped = true;
            break;
        case 'kart':
            allies.forEach(a => changeStage(a, {Spe:1}));
            break;
        case 'bibitone':
            healPoke(attacker, 0.5);
            changeStage(attacker, {Def:1, Atk:1});
            break;
        case 'all_in': break; // gestito interamente in executeSingleAction (KO/self-KO)
        case 'alla_lavagna':
            if (ctx.failed) break;
            enemyActive(attacker.trainerId).forEach(e => { if (e.v.lastMoveUsed) e.v.forcedMove = { name: e.v.lastMoveUsed, turnsLeft: 2 }; });
            break;
        case 'whisky':
            if (defender) { tryInflictStatus(defender, 'Confuso'); defender.types = ['Alcol']; }
            if (attacker.name === 'Ressa') healPoke(attacker, 0.15);
            break;
        case 'mignolo_appuntito':
            if (defender) defender.stages.Atk = clampStage(defender.stages.Atk); // dimezza valore effettivo -> applichiamo come flag
            if (defender) defender.v.atkHalved = true;
            break;
        case 'signorina_daloia': break; // moltiplicatore gestito in computeDamage extra
        case 'esame_sorpresa':
            allPokemonEffectTargets.filter(p=>p.types.includes('Ingegno')).forEach(p => changeStage(p, {Spe:-1, SpA:-1, SpD:-1}));
            break;
        case 'gender_pay_gap':
            allPokemonEffectTargets.forEach(p => {
                if (p.gender === 'Maschio') changeStage(p, {Atk:-1, SpA:-1});
                else changeStage(p, {Atk:1, SpA:1});
            });
            break;
        case 'subito_a_casa': {
            if (!defender) break;
            const bench = (defender.trainerId===1?gameState.p1Team:gameState.p2Team).filter(p=>!p.isFainted && p.activeSlot===null);
            if (bench.length === 0) { printLog(`Subito a Casa! fallisce: nessun sostituto disponibile.`); break; }
            const slot = defender.activeSlot;
            const replacement = isBotMode() && defender.trainerId === 2
                ? chooseBotSwitch(defender.trainerId, slot, bench)
                : bench[0];
            directSwitchIn(defender.trainerId, slot, replacement);
            break;
        }
        case 'bomba_maradona': break; // STAB forzato già gestito nei dati (stab:true)
        case 'step_back':
            attacker.types = ['Fitness'];
            changeStage(attacker, {Spe:2});
            break;
        case 'pizza_time':
            healPoke(attacker, 0.5);
            break;
        case 'bang': break;
        case 'briscola_gigante':
            setTerreno('Calabro', attacker);
            break;
        case 'rifiuto':
            handleProtect(attacker, 'males');
            break;
        case 'depilazione_laser':
            changeStage(attacker, {Def:-1, SpD:-1});
            break;
        case 'cinematografo':
            allActive().filter(p=>p!==attacker).forEach(p => tryInflictStatus(p, 'Confuso'));
            break;
        case 'ringraziando_iddio': {
            const side = attacker.trainerId===1?gameState.p1Side:gameState.p2Side;
            side.dmgReductionPct = 0.2; side.dmgReductionTurns = 3;
            printLog(`🙏 La squadra di Giocatore ${attacker.trainerId} riduce i danni subiti del 20% per 3 turni!`);
            break;
        }
        case 'cuscino_peloso':
            if (defender) {
                defender.status = { type:'Sleep', counter:0, sleepTurns:0 };
                defender.hp = defender.maxHp;
                defender.v.fungo = false; defender.v.da = false; defender.v.confused = false;
                printLog(`😴 ${pname(defender)} viene addormentato ma curato e portato a HP pieni!`);
            }
            break;
        case 'ordine_glovo':
            changeStage(attacker, {Def:3, SpD:3});
            healPoke(attacker, 1/3);
            break;
        case 'serie_tv':
            enemyActive(attacker.trainerId).forEach(e => changeStage(e, {Spe:-1}));
            break;
        case 'padel_hits': break; // multi-hit gestito nel wrapper sotto
        case 'heets':
            if (defender) tryInflictStatus(defender, 'Confuso');
            break;
        case 'grattini':
            if (defender) {
                const bonus = defender.name === 'Steo' ? 2 : 1;
                changeStage(defender, {Def:bonus, SpD:bonus});
            }
            break;
        case 'scoordinato':
            tryInflictStatus(attacker, 'Confuso');
            break;
        case 'fluidodinamica': break; // raddoppio danno vs Alcol gestito in computeDamage
        case 'lavoro_gruppo':
            allies.filter(a=>a.types.includes('Ingegno')).forEach(a => changeStage(a, {Spe:1, SpD:1, SpA:1}));
            break;
        case 'insulto_maschilista': break; // dimezzato vs maschio gestito in computeDamage extra
        case 'scambio_geografico': {
            const ally = allyOf(attacker);
            if (ally) {
                const aSlot = attacker.activeSlot, allySlot = ally.activeSlot;
                const active = attacker.trainerId===1?gameState.p1Active:gameState.p2Active;
                active[aSlot] = ally; active[allySlot] = attacker;
                attacker.activeSlot = allySlot; ally.activeSlot = aSlot;
                printLog(`🔀 ${pname(attacker)} e ${pname(ally)} si scambiano di posto!`);
            }
            break;
        }
        case 'puttana':
            if (defender && defender.gender === 'Femmina') {
                changeStage(defender, {Def:-1, SpD:-1, Atk:1, SpA:1, Spe:1});
            } else { printLog(`Puttana! non ha effetto: il bersaglio non è Femmina.`); }
            break;
    }

    onComplete();
}

/* Gestione mosse "protect" con probabilità di fallimento crescente */
function handleProtect(poke, mode) {
    poke.v.protectStreak = (poke.v.lastProtectRound === gameState.roundNumber - 1) ? poke.v.protectStreak + 1 : 0;
    poke.v.lastProtectRound = gameState.roundNumber;
    const failChance = [0, 0.5, 0.99, 1.0][Math.min(poke.v.protectStreak, 3)];
    if (Math.random() < failChance) { printLog(`🛡️ ${pname(poke)} fallisce nel proteggersi questa volta!`); return; }
    if (mode === 'all') { poke.v.protectedThisTurn = true; printLog(`🛡️ ${pname(poke)} si protegge da qualsiasi attacco!`); }
    if (mode === 'males') { poke.v.protectedFromMalesThisTurn = true; printLog(`🛡️ ${pname(poke)} si protegge dagli attacchi dei Pokemon Maschi!`); }
}

/* Danni extra situazionali (moltiplicatori dipendenti da move.effect) applicati come wrapper */
const _origComputeDamage = computeDamage;
computeDamage = function(attacker, defender, move, opts) {
    const result = _origComputeDamage(attacker, defender, move, opts);
    if (result.tMod === 0) return result;
    let dmg = result.dmg;
    if (move.effect === 'squarta_neri' && (defender.types.includes('Esotico') || defender.types.includes('Terrone'))) dmg *= 3;
    if (move.effect === 'signorina_daloia' && defender.gender === 'Femmina') dmg *= 3;
    if (move.effect === 'insulto_maschilista' && defender.gender === 'Maschio') dmg = Math.floor(dmg / 2);
    if (move.effect === 'viva_il_duce') {
        const otherMales = (attacker.trainerId===1?gameState.p1Team:gameState.p2Team).filter(p=>p!==attacker && p.gender==='Maschio' && !p.isFainted).length;
        // BP effettivo già fisso a 40 nei dati; applichiamo bonus proporzionale come moltiplicatore equivalente
        dmg = Math.floor(dmg * (40 + 20*otherMales) / 40);
    }
    if (attacker.v.atkHalved) dmg = Math.floor(dmg * 0.5);
    return { dmg: Math.max(1, dmg), tMod: result.tMod };
};

/* Multi-hit (spara sushi 2-5, Colpo di Padel 2-4) gestiti come hit multipli extra dopo il colpo base.
   Il wrapper aspetta il completamento (sincrono o asincrono) dell'azione originale prima di
   applicare i colpi aggiuntivi, e solo dopo richiama l'onComplete esterno. La protezione del
   bersaglio (calcolata PRIMA che l'azione originale venga eseguita, così come farebbe per il
   primo colpo) blocca anche tutti i colpi aggiuntivi, non solo il primo. */
const _origExecuteSingleAction = executeSingleAction;
executeSingleAction = function(attacker, defender, move, flinchedSet, onComplete) {
    onComplete = onComplete || function(){};
    const wasProtected = !!(defender && move.target === 'Single Target' && isProtected(defender, attacker, move));
    _origExecuteSingleAction(attacker, defender, move, flinchedSet, () => {
        if (!wasProtected && (move.effect === 'multi_hit' || move.effect === 'padel_hits') && defender && !defender.isFainted && !attacker.isFainted) {
            const extraHits = move.effect === 'multi_hit' ? (Math.floor(Math.random()*4)+1) : (Math.floor(Math.random()*2)+1); // hit totali già 1 fatto sopra: aggiungiamo da 1 a 4 (tot 2-5) o 1-2 (tot 2-3~4)
            for (let i=0;i<extraHits && !defender.isFainted;i++) {
                const { dmg, tMod } = computeDamage(attacker, defender, move, { isCrit:false, numTargets:1 });
                if (tMod === 0) break;
                defender.hp = Math.max(0, defender.hp - dmg);
                printLog(`💥 Colpo aggiuntivo: ${pname(defender)} subisce ${dmg} danni!`);
                if (defender.hp === 0) { defender.isFainted = true; printLog(`💀 ${pname(defender)} è andato KO!`); handleFaint(defender); }
            }
        }
        onComplete();
    });
};

/* =========================================================================
   FINE TURNO: status, campo, rientri, switch forzati
   ========================================================================= */
function endOfRoundEffects() {
    // rientro Pausa Siga: Giana (o chi ha usato la mossa) riprende il proprio slot,
    // rimandando in panchina il sostituto temporaneo (se ancora in campo e vivo).
    if (gameState.pendingReturn && gameState.pendingReturn.length) {
        gameState.pendingReturn.forEach(entry => {
            if (entry.poke.isFainted) return;
            const active = entry.trainerId===1?gameState.p1Active:gameState.p2Active;
            const current = active[entry.slot];
            if (current === entry.poke) return; // già al suo posto
            if (current) current.resetOnSwitchOut();
            active[entry.slot] = entry.poke;
            entry.poke.activeSlot = entry.slot;
            printLog(`🚬 ${pname(entry.poke)} rientra in campo dopo la pausa sigaretta!`);
            triggerEntryAbility(entry.poke);
        });
        gameState.pendingReturn = [];
    }

    allActive().forEach(p => {
        if (p.isFainted) return;
        if (p.status.type === 'Burn') { const d = Math.floor(p.maxHp/16); p.hp = Math.max(0,p.hp-d); printLog(`🔥 ${pname(p)} subisce ${d} danni da Burn.`); }
        if (p.status.type === 'Iperavvelenato') {
            p.status.counter = (p.status.counter||0) + 1;
            const frac = Math.min(1, Math.pow(2, p.status.counter-1) / 16);
            const d = Math.floor(p.maxHp * frac);
            p.hp = Math.max(0, p.hp - d);
            printLog(`☠️ ${pname(p)} subisce ${d} danni da Iperavvelenamento.`);
        }
        if (p.v.fungo) { const d = Math.floor(p.maxHp/8); p.hp = Math.max(0,p.hp-d); printLog(`🍄 ${pname(p)} subisce ${d} danni da Fungo.`); }
        if (p.hp === 0 && !p.isFainted) { p.isFainted = true; printLog(`💀 ${pname(p)} è andato KO per lo stato!`); }
    });

    if (gameState.field.clima === 'Fumo') {
        allActive().forEach(p => {
            if (p.isFainted || p.types.includes('Fumo')) return;
            const frac = (p.types.includes('Fitness') || p.types.includes('Puro')) ? 1/10 : 1/16;
            const d = Math.floor(p.maxHp * frac);
            p.hp = Math.max(0, p.hp - d);
            printLog(`☁️ ${pname(p)} subisce ${d} danni dal Clima Fumo.`);
            if (p.hp === 0) { p.isFainted = true; printLog(`💀 ${pname(p)} è andato KO per il Clima!`); }
        });
    }

    // svuota gli slot di chi è appena andato KO per stato/clima (i cicli sopra impostano
    // solo isFainted, senza toccare l'array degli attivi)
    clearFaintedActiveSlots();

    // riduzione contatori
    if (gameState.field.terrenoTurns > 0 && --gameState.field.terrenoTurns === 0) { printLog(`🌿 Il Terreno ${gameState.field.terreno} svanisce.`); gameState.field.terreno = null; }
    if (gameState.field.climaTurns > 0 && --gameState.field.climaTurns === 0) { printLog(`☁️ Il Clima ${gameState.field.clima} svanisce.`); gameState.field.clima = null; }
    [gameState.p1Side, gameState.p2Side].forEach(s => { if (s.dmgReductionTurns > 0 && --s.dmgReductionTurns === 0) s.dmgReductionPct = 0; });

    allActive().forEach(p => {
        Object.keys(p.v.moveLockout).forEach(mv => { if (p.v.moveLockout[mv] > 0) p.v.moveLockout[mv]--; });
        if (p.v.redirectTurns > 0) p.v.redirectTurns--;
    });

    // A questo punto tutte le mosse e gli effetti di fine turno sono stati risolti: aggiorniamo
    // subito il tabellone (HP, KO, status, stage) così riflette la situazione reale dopo il
    // turno appena concluso, PRIMA di fermarci con il bottone "Prosegui al prossimo turno" al
    // posto della griglia mosse. Così il giocatore vede l'esito effettivo mentre legge il log,
    // e solo al click si procede con eventuali sostituzioni forzate per KO.
    updateUI();
    showContinueButton();
}

function finishRound() {
    roundActions = [];
    currentTrainerTurn = 1;
    currentSlotTurn = 0;
    updateUI();
    if (!checkWinner()) {
        // Il popup è necessario solo nella partita locale.
        if (isBotMode()) promptNextMove();
        else showPassDevice(1, () => promptNextMove());
    }
}

// Trova tutti gli slot vuoti (di entrambi i giocatori) che hanno ancora un sostituto
// disponibile in panchina, e li mette in coda per essere risolti uno alla volta con
// un modale ciascuno. Al termine della coda invoca onAllResolved.
function handleForcedSwitches(onAllResolved) {
    const queue = [];
    [1,2].forEach(trainerId => {
        const active = trainerId===1?gameState.p1Active:gameState.p2Active;
        for (let i=0;i<2;i++) {
            if (active[i] === null) {
                const bench = (trainerId===1?gameState.p1Team:gameState.p2Team).filter(p=>!p.isFainted && p.activeSlot===null);
                if (bench.length > 0) queue.push({ trainerId, slot:i });
                // se la panchina è vuota, lo slot resta vuoto: la squadra è stata spazzata
                // e checkWinner() (chiamato in finishRound) se ne accorgerà.
            }
        }
    });

    if (queue.length === 0) {
        gameState.phase = 'battle';
        if (onAllResolved) onAllResolved();
        return;
    }

    gameState.phase = 'forced-switch';
    processForcedSwitchQueue(queue, 0, onAllResolved);
}

function processForcedSwitchQueue(queue, idx, onAllResolved) {
    if (idx >= queue.length) {
        gameState.phase = 'battle';
        if (onAllResolved) onAllResolved();
        return;
    }
    const { trainerId, slot } = queue[idx];
    const active = trainerId===1?gameState.p1Active:gameState.p2Active;
    if (active[slot] !== null) { processForcedSwitchQueue(queue, idx+1, onAllResolved); return; } // già riempito nel frattempo
    const bench = (trainerId===1?gameState.p1Team:gameState.p2Team).filter(p=>!p.isFainted && p.activeSlot===null);
    if (bench.length === 0) { processForcedSwitchQueue(queue, idx+1, onAllResolved); return; }

    if (isBotMode() && trainerId === 2) {
        const replacement = chooseBotSwitch(trainerId, slot, bench);
        if (replacement) {
            printLog(`⏳ Il Bot manda in campo ${replacement.name} nello slot ${slot+1}.`);
            directSwitchIn(trainerId, slot, replacement);
            processForcedSwitchQueue(queue, idx+1, onAllResolved);
            return;
        }
    }

    printLog(`⏳ Giocatore ${trainerId} deve mandare in campo un nuovo Pokémon nello slot ${slot+1}.`);
    showModal(`Giocatore ${trainerId}: scegli il prossimo Pokémon (slot ${slot+1})`, bench.map(b => ({
        label: `${b.name} (HP ${b.hp}/${b.maxHp})`,
        onClick: () => {
            directSwitchIn(trainerId, slot, b);
            processForcedSwitchQueue(queue, idx+1, onAllResolved);
        }
    })));
}

window.onload = () => {
    initRosterSelection();
    showModeSelection();
};